def solution(input_string):
    import sys
    from io import StringIO
    from collections import deque

    input_data = StringIO(input_string)
    reader = lambda: input_data.readline().strip()

    def parse_test_cases():
        t_line = reader()
        while t_line == '':
            t_line = reader()
        t = int(t_line)

        test_cases = []
        for _ in range(t):
            # Skip empty line before each test case
            while reader() == '':
                pass
            n_line = reader()
            while n_line == '':
                n_line = reader()
            n = int(n_line)

            nodes = []
            for i in range(n):
                line = reader()
                parts = list(map(int, line.split()))
                if parts[0] == -1:
                    nodes.append({'type': 'node', 'left': parts[1], 'right': parts[2]})
                else:
                    nodes.append({'type': 'leaf', 'value': parts[0]})
            test_cases.append(nodes)
        return test_cases

    def solve(nodes):
        # Build the tree structure and find leaf values
        def find_leaf(node):
            if node['type'] == 'node':
                return (find_leaf(node['left']), find_leaf(node['right']))
            else:
                return (node)

        def solve_tree(node, depth):
            if node['type'] == 'leaf':
                return node['value']
            else:
                left_child, right_child = find_leaf(node)
                left_val = solve_tree(left_child, depth + 1)
                right_val = solve_tree(right_child, depth + 1)
                return max(left_val, right_val)

        return solve_tree(nodes[0], 0)

    # Parse all test cases
    test_cases = parse_test_cases()

    results = []
    for nodes in test_cases:
        results.append(str(solve(nodes)))

    return '\n'.join(results)

import sys
from typing import List, Tuple

def check_line_intersection(a1, a2, b1, b2):
    """Check if line segments (a1, a2) and (b1, b2) intersect."""
    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    d1 = cross_product(b1, b2, a1)
    d2 = cross_product(b1, b2, a2)
    d3 = cross_product(a1, a2, b1)
    d4 = cross_product(a1, a2, b2)

    if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
       ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
        return True

    return False

def get_convex_hull(points):
    """Computes the convex hull using Andrew's monotone chain algorithm."""
    points = sorted(points, key=lambda p: (p[0], p[1]))

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    N = int(lines[0])

    ships = []
    for i in range(1, N + 1):
        x, y = map(int, lines[i].split())
        ships.append((x, y, i))

    bases = []
    for i in range(N + 1, 2 * N + 1):
        x, y = map(int, lines[i].split())
        bases.append((x, y, i))

    all_points = ships + bases
    hull = get_convex_hull(all_points)

    if len(hull) == 2:
        return f"{hull[0][2]}\n{hull[1][2]}\n1\n2\n" if len(hull[2:]) > 0 else f"{hull[0][2]}\n{hull[1][2]}\n"

    rnd = [set(range(N)) for _ in range(N)]
    result = [0] * N

    def try_match(i, j):
        if i >= N or j >= N or i in rnd[j] or j >= N:
            return False
        if i < j and check_line_intersection(ships[i], bases[j], result[i], result[j]):
            return False

        result[i] = j + 1
        rnd[j].add(i)
        return True

    for i in range(N):
        if result[i] == 0:
            has_any = False
            for j in range(N):
                if i in rnd[j] or j in rnd[i]:
                    continue
                if check_line_intersection(ships[i], bases[j], result[j], result[i]):
                    continue
                rnd[i].add(j)
                result[i] = j + 1
                has_any = True
                break
            if not has_any:
                pass

    matched = set()
    for i in range(N):
        if result[i] == 0:
            found = False
            for j in range(N):
                if j < i or result[i] == j + 1:
                    continue
                if check_line_intersection(ships[i], bases[j], ships[j], bases[i]):
                    continue
                result[i] = j + 1
                found = True
                break
            if not found:
                result[i] = 1

    output = []
    for i in range(N):
        output.append(str(result[i]))
    return '\n'.join(output)

