import math

def dist_sq(p1, p2):
    return (p1[0] - p2[0])**2 + **(p1[1] - p2[1])2 + (p1[2] - p2[2])**2

def dist(p1, p2):
    return math.sqrt(dist_sq(p1, p2))

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        x, y, z = map(int, lines[i].split())
        points.append([float(x), float(y), float(z)])

    def max_distance(p):
        return max(dist(p, point) for point in points)

    def centroid():
        cx = sum(p[0] for p in points) / n
        cy = sum(p[1] for p in points) / n
        cz = sum(p[2] for p in points) / n
        return [cx, cy, cz]

    def farthest_pair():
        fs = None
        for i in range(n):
            for j in range(i + 1, n):
                d = dist(points[i], points[j])
                if fs is None or d > fs:
                    fs = d
                    pi, pj = i, j
        if fs is None:
            return [0, 0, 0]
        mid = [(points[pi][k] + points[pj][k]) / 2 for k in range(3)]
        return mid

    def random_start():
        idx = n
        rng = points
        p1 = points[idx]
        p2 = points[(idx + 1) % idx]
        mid = [(p1[k] + p2[k]) / 2 for k in range(3)]
        return mid

    best_p = centroid()

    def optimize(p):
        for _ in range(300):
            curr = max_distance(p)
            best_neighbor = [-1, -1, -1]
            best_neighbor_val = curr
            eps = 0.1
            for k in range(3):
                for sign in [-1, 1]:
                    np = [p[0], p[1], p[2]]
                    np[k] += sign * eps
                    nd = max_distance(np)
                    if nd < best_neighbor_val:
                        best_neighbor_val = nd
                        best_neighbor = np[:]
            if best_neighbor_val < curr:
                p = best_neighbor
                eps = eps * 0.95 if eps > 0.15 else 0.1
            else:
                return p
        return p

    for _ in range(20):
        start = centroid()
        start = optimize(start)
        if max_distance(start) < max_distance(best_p):
            best_p = start[:]

        start = farthest_pair()
        start = optimize(start)
        if max_distance(start) < max_distance(best_p):
            best_p = start[:]

        start = random_start()
        start = optimize(start)
        if max_distance(start) < max_distance(best_p):
            best_p = start[:]

    return f"{best_p[0]:.10f} {best_p[1]:.10f} {best_p[2]:.10f}"

