# Increase recursion limit for deep trees
sys.setrecursionlimit(200000)


class DSU:
    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.rank = [0] * (n + 1)

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return False
        if self.rank[px] < self.rank[py]:
            px, py = py, px
        self.parent[py] = px
        if self.rank[px] == self.rank[py]:
            self.rank[px] += 1
        return True


class Solution:
    def solution(self, input_str: str) -> str:
        lines = input_str.strip().split('\n')
        n, m = map(int, lines[0].split())
        edges = []
        for i in range(m):
            a, b, e = map(int, lines[i + 1].split())
            edges.append((a, b, e, i))

        # Sort edges by weight
        sorted_edges = sorted(edges, key=lambda x: x[2])

        # Build MST
        dsu = DSU(n)
        min_edges = []
        edge_idx = [0] * m  # Track original index of each edge in MST
        for a, b, e, orig_idx in sorted_edges:
            if dsu.union(a, b):
                min_edges.append((a, b, e, orig_idx))
                edge_idx[orig_idx] = 1

        # Build adjacency list for weighted MST
        adj = [[[] for _ in range(n + 1)] for _ in range(n)]  # adj[u] = [(v, w)]
        for a, b, e, _ in min_edges:
            weighted_adj = [[None, None]] * (n + 1)
            adj[a].append((b, e))
            adj[b].append((a, e))

        # Preprocess for LCA with binary lifting on MST
        parent = [0] * (n + 1)
        depth = [0] * (n + 1)
        max_edge_on_path = [0] * (n + 1)  # max_edge_on_path[u] = (u, p, w, alt_w) where on path to lca
        LOG = 20
        up = [[0] * (n + 1) for _ in range(LOG)]
        max_weight_on_path = [[0] * (n + 1) for _ in range(LOG)]  # max weight edge from u to 2^i-th ancestor

        def dfs(u, p = 0, w = 0):
            depth[u] = depth[p] if p != 0 else 0
            up[0][u] = p
            max_weight_on_path[0][u] = w
            for i in range(1, LOG):
                if up[i-1][u] != 0:
                    up[i][u] = up[i-1][up[i-1][u]]
                    max_weight_on_path[i][u] = max(max_weight_on_path[i-1][u], 
                                                      max_weight_on_path[i-1][up[i-1][u]])
                else:
                    up[i][u] = 0
                    max_weight_on_path[i][u] = 0
            for v, weight in adj[u]:
                if v != p:
                    dfs(v, u, weight)

        dfs(1)

        # Find max weight on path between u and v in MST
        def max_weight_path(u, v):
            if depth[u] < depth[v]:
                u, v = v, u

            # Lift v to same depth as u
            max_w = 0
            diff = depth[u] - depth[v]
            for i in range(LOG):
                if diff & (1 << i):
                    max_w = max(max_w, max_weight_on_path[i][v])
                    v = up[i][v]

            if u == v:
                return max_w

            # Lift both to LCA
            for i in range(LOG - 1, -1, -1):
                if up[i][u] != up[i][v]:
                    max_w = max(max_w, max_weight_on_path[i][u])
                    max_w = max(max_w, max_weight_on_path[i][v])
                    u = up[i][u]
                    v = up[i][v]

            return max(max_w, max_weight_on_path[0][u], max_weight_on_path[0][v])

        # Output results for non-MST edges
        results = []
        non_mst_edges = [e for e in sorted_edges if edge_idx[e[3]] == 0]
        for _, _, orig_idx, _ in sorted_edges:
            edge_idx[orig_idx] = 0  # Reset

        # Find which edges are not in MST
        for a, b, _, idx in edges:
            non_mst_edges.append((a, b, edges[idx][2], idx))

        for _, _, original_weight, idx in non_mst_edges:
            e_val = max_weight_path(idx, idx)
            results.append(f"{e_val}\n")

        return ''.join(results)

