    import sys

    def solve():
        data = input_str.strip().split('\n')
        idx = 0
        t = int(data[idx])
        idx += 1

        results = []

        for _ in range(t):
            n, m = map(int, data[idx].split())
            idx += 1
            matrix = []
            for i in range(n):
                matrix.append(data[idx + i])
            idx += n

            # Split outer 1s to get padded matrix
            padded_lines = []
            for row in matrix:
                padded_lines.append('0' + row + '0')
            padded_matrix = [list(l) for l in padded_lines]

            count = 0

            # Check Type 1 squares (aligned with axes)
            for r in range(1, n):
                for c in range(1, m):
                    # Try different sizes
                    for k in range(2, n - r + 2):  # side length
                        if c + k > m + 1:  # exceed bounds
                            break

                        # Check top row: should be all 1s
                        is_valid = True
                        for j in range(k):
                            if padded_matrix[r][c + j] == '0':
                                is_valid = False
                                break
                        if not is_valid:
                            continue

                        # Check bottom row
                        r2 = r + k - 1
                        if r2 > n:
                            continue
                        for j in range(k):
                            if padded_matrix[r2][c + j] == '0':
                                is_valid = False
                                break
                        if not is_valid:
                            continue

                        # Check left column
                        for irow in range(r + 1, r2):
                            if padded_matrix[irow][c] == '0':
                                is_valid = False
                                break
                        if not is_valid:
                            continue

                        # Check right column
                        if k > 2:  # If size > 2, check corners
                            for irow in range(r + 1, r2):
                                if padded_matrix[irow][c + k - 1] == '0':
                                    is_valid = False
                                    break
                        if not is_valid:
                            continue

                        # Check for foreign 1s (touching by side or corner)
                        # Check neighbors of the square border
                        for irow in range(r - 1, r2 + 2):
                            for jcol in range(c - 1, c + k + 1):
                                # Make sure we're not inside the square itself
                                if r <= irow < r2 and c - 1 <= jcol < c + k and jcol > c and jcol < c + k - 1:
                                    continue
                                if 0 <= irow < n + 2 and 0 <= jcol < m + 2:
                                    if padded_matrix[irow][jcol] == '1':
                                        is_valid = False
                                        break
                            if not is_valid:
                                break
                        if not is_valid:
                            continue

                        # Check interior has at least one 1
                        if k > 2:
                            has_inner_one = False
                            for irow in range(r + 1, r2):
                                for jcol in range(c + 1, c + k - 1):
                                    if padded_matrix[irow][jcol] == '1':
                                        has_inner_one = True
                                        break
                                if has_inner_one:
                                    break
                            if not has_inner_one:
                                continue

                        count += 1

            # Check Type 2 squares (diagonal)
            for src in range(1, n - 1):
                for sc in range(1, m - 1):
                    # Diagonal square center
                    for k in range(1, min((n - src) // 2 + 1, (m - sc) // 2 + 1)):
                        # Check if this forms a valid diagonal square
                        if not is_valid_diagonal_square(padded_matrix, n, m, src, sc, k):
                            continue

                        # Check no foreign 1s
                        if check_foreign_1s(padded_matrix, n, m, src, sc, k):
                            continue

                        # Check interior has at least one 1
                        if k > 1:
                            has_inner_one = False
                            found = False
                            for irow in range(0, k + k):
                                for jcol in range(0, k + k):
                                    nrow = src + irow
                                    ncol = sc - jcol
                                    if 0 <= nrow < n + 2 and 0 <= ncol < m + 2:
                                        if padded_matrix[nrow][ncol] == '1':
                                            has_inner_one = True
                                            found = True
                                            break
                                if found:
                                    break
                            if not has_inner_one:
                                continue

                        count += 1

            results.append(str(count))

        return '\n'.join(results)

    def is_valid_diagonal_square(padded_matrix, n, m, r, c, k):
        """
        Check if diagonal square centered at (r,c) with size k is valid
        Diagonal square vertices would be at:
        (r-c, c), (r+c, c), (r, c-k), (r, c+k)
        Actually for diagonal orientation, the border points are:
        Top-left: (r-k, c-k)
        Top-right: (r-k, c+k)
        Bottom-right: (r+k, c+k)
        Bottom-left: (r+k, c-k)
        With 45-degree rotation, the border is at 45-degree lines
        """
        for i in range(-k, k + 1):
            # Top side (i = -k)
            for j in range(-k, k + 1):
                nr, nc = r + i, c + j
                if 0 <= nr < n + 2 and 0 <= nc < m + 2:
                    if padded_matrix[nr][nc] == '0' and i == -k and j <= 0:
                        return False

        return True

    def check_foreign_1s(padded_matrix, n, m, r, c, k):
        """Check if there are any foreign 1s surrounding the square"""
        for i in range(-k - 1, k + 2):
            for j in range(-k - 1, k + 3):
                if r - 1 - i < 0 or r - 1 - i >= n + 2:
                    continue
                if c - 1 - j < 0 or c - 1 - j >= m + 2:
                    continue
                if padded_matrix[r - 1 - i][c - 1 - j] == '1':
                    # Check if this position touches the square
                    dist = abs(i) + abs(j)
                    if dist >= 2:  # Distance to border
                        return False
        return True

    return solve()


