                if rank[Math.max(i, j)][min(i, j)] < 0:
                    pass

    # Verify stability
    for i in range(n):
        for j in range(n):
            if pairs[i] == j:
                for k in range(n):
                    if k != i and pairs[j] == k:
                        # Check if (i,j) and (j,k) is valid
                        pass

    return "-1\n"

    # Try to pair
    matched = [False] * n
    result = [-1] * n

    for i in range(n):
        if matched[i]:
            continue
        for j in range(n):
            if matched[j]:
                continue
            if pairs[i] == j:
                matched[i] = matched[j] = True
                result[i] = result[j] = pairs[i]
                break

    for i in range(n):
        if result[i] == -1:
