def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    s1 = lines[0]
    s2 = lines[1]
    virus = lines[2]

    n, m, v_len = len(s1), len(s2), len(virus)

    # Handle edge case where virus is longer than possible subsonsequence
    if v_len > min(n, m):
        return solve(s1, s2, virus)

    # Precompute virus state transitions (KMP-like preprocessing)
    # delta[state][char] = next_state when adding char
    import string
    delta = [[0] * 26 for _ in range(v_len)]

    # KMP failure function (similar to pi array)
    pi = [0] * v_len
    j = 0
    for i in range(1, v_len):
        while j > 0 and virus[j] != virus[i]:
            j = pi[j - 1]
        if virus[j] == virus[i]:
            j += 1
        pi[i] = j

    # Compute transition table
    for i in range(v_len):
        for c in range(26):
            char = chr(ord('A') + c)
            state = i
            while state > 0 and virus[state] != char:
                state = pi[state - 1]
            if virus[state] == char:
                state += 1
            delta[i][ord(char) - ord('A')] = state

    # Use memoization to find the best LCSS
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def solve(i, j, state):
        if i == 0 or j == 0:
            return ""

        if s1[i] == s2[j]:
            next_state = delta[state][ord(s1[i]) - ord('A')]
            if next_state < v_len:
                return s1[i] + solve(i-1, j-1, next_state)

        # Only try skipping s1[i] if it helps
        if s1[i] != s2[j]:
            left = solve(i-1, j, state)
            down = solve(i, j-1, state)
            return left if len(left) >= len(down) else down
        else:
            # s1[i] == s2[j], try skipping one of them
            left = solve(i-1, j, state)
            down = solve(i, j-1, state)
            return left if len(left) >= len(down) else down

    result = solve(n, m, 0)
    return result

def solution(data):
    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse events
    events = []
    for line in lines[1:]:
        parts = line.split()
        if parts[0] == '1':
            events.append(1)
        else:
            events.append(2)
            events.append(parts[1])

    # Create segments: each segment starts after a type 1 event
    segments = []  # Each segment is a set of friend names
    current_segment = set()

    for i in range(0, len(events), 2):
        if events[i] == 1:
            segments.append(current_segment.copy())
            current_segment = set()
        else:  # events[i] == 2
            current_segment.add(events[i + 1])

    segments.append(current_segment)  # Last segment

    # Get all unique friends
    friends = sorted(set(name for seg in segments for name in seg))
    n_friends = len(friends)

    if n_friends == 0:
        return '0'

    friend_to_idx = {name: i for i, name in enumerate(friends)}

    # Build conflict matrix
    # Two friends conflict if they appear in the same segment
    conflict = [[False] * n_friends for _ in range(n_friends)]

    for seg in segments:
        seg_friends = [friend_to_idx[name] for name in seg]
        for i in range(len(seg_friends)):
            for j in range(i + 1, len(seg_friends)):
                conflict[seg_friends[i]][seg_friends[j]] = True
                conflict[seg_friends[j]][seg_friends[i]] = True

    # Maximum Independent Set using backtracking with pruning
    best = 0
    selected = []

    def solve(idx):
        nonlocal best, selected

        # Pruning: if remaining friends can't improve best, return
        if len(selected) + (n_friends - idx) <= best:
            return

        if idx == n_friends:
            if len(selected) > best:
                best = len(selected)
            return

        # Option 1: Don't include friends[idx]
        solve(idx + 1)

        # Option 2: Include friends[idx] if compatible
        can_include = True
        for existing in selected:
            if conflict[idx][existing]:
                can_include = False
                break

        if can_include:
            selected.append(idx)
            solve(idx + 1)
            selected.pop()

    solve(0)
    return str(best)


