        # Parse coefficient
        coeff = 1
        if expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            coeff = int(expr[i:j])
            i = j
        else:
            i += 1  # skip possible leading + to the increment

        # Determine increment type
        if i + 2 <= len(expr) and expr[i:i+3] == 'a++':
            is_post = True
            i += 3
        elif i + 3 <= len(expr) and expr[i:i+4] == '++a':
            is_post = False
            i += 4
        elif i < len(expr) and expr[i] == '+' and i + 1 < len(expr) and expr[i+1] == '+' and i + 2 < len(expr) and expr[i+2] == 'a':
            is_post = False
            i += 3
        elif i < len(expr) and expr[i] == 'a' and i + 2 < len(expr) and expr[i+1:i+3] == '++':
            is_post = True
            i += 3
        else:
            # Handle 'a++' pattern that might have extra + chars after
            is_post = True
            while i < len(expr) and expr[i] == '+':
                i += 1
            if i < len(expr) and (i < len(expr) - 1 and expr[i] == '+' or i == len(expr)):
                i += 2
            else:
                i += 1  # skip 'a'

        summands.append({'coeff': coeff, 'is_post': is_post, 'neg': neg})
        neg = not neg
        i += 1

    # Sort summands to maximize the total
    # Strategy: post-increments with negative coefficients first,
    # then post-increments with positive coefficients,
    # then pre-increments with negative coefficients,
    # finally pre-increments with positive coefficients
    def sort_key(s):
        if s['is_post']:
            if s['neg']:
                return (0, s['coeff'])
            else:
                return (1, s['coeff'])
        else: # is_pre
            if s['neg']:
                return (2, -s['coeff'])
            else:
                return (3, s['coeff'])

    summands.sort(key=sort_key)

    # Calculate total with initial a
    total = 0

    for s in summands:
        if s['is_post']:
            # a++: multiply by current a, then increment
            total += s['coeff'] * a
            a += 1
        else:
            # ++a: increment, then multiply by current a
            a += 1
            total += s['coeff'] * a

    if neg:
        total = -total

    return str(total) + '\n'

