    lines = input_data.strip().split('\n')
    n, x0, y0 = int(lines[0].split()), lines[0].split()[1], lines[0].split()[2]
    x0, y0 = int(x0), int(y0)

    grid = []
    for i in range(1, n + 1):
        row = list(map(int, lines[i].split()))
        grid.append(row)

    # Convert to 1-indexed for convenience  
    grid = [[0] + grid[j] + [0] for j in range(n)]

    dx = {0: 0, 1: 0, 2: -1, 3: 1}  # U, D
    dy = {0: -1, 1: 1, 2: 0, 3: 0}

    directions = {'U': (0, -1), 'D': (0, 1), 'L': (-1, 0), 'R': (1, 0)}

    def can_see_light(lights, x, y, dx_dir, dy_dir):
        """Check if there's a light in the given direction from (x,y)"""
        nx, ny = x + dx_dir, y + dy_dir
        while 1 <= nx <= n and 1 <= ny <= n:
            if lights[nx][ny] == 1:
                return True
            nx += dx_dir
            ny += dy_dir
        return False

    def turn_all_off(lights, path):
        """Count how many lights are on"""
        for i in range(1, n+1):
            for j in range(1, n+1):
                if lights[i][j] == 1:
                    return False, path
        return True, path

    def backtrack(lights, x, y, path_and_return):
        """DFS to try all possibilities"""
        # Check if all lights off and we're at start
        all_off, return_path = turn_all_off(lights, path_and_return)
        if all_off:
            return "YES\n" + path_and_return
        if x == x0 and y == y0:
            return None

        # Try each operation
        # 1. Turn on light (if off)
        if lights[x][y] == 0:
            lights[x][y] = 1
            result = backtrack(lights, x, y, path_and_return + "1")
            if result:
                return result + "2"
            lights[x][y] = 0

        # 2. Turn off light (if on) and not at start
        if lights[x][y] == 1 and (x != x0 or y != y0):
            lights[x][y] = 0
            result = backtrack(lights, x, y, path_and_return + "2")
            if result:
                return result
            lights[x][y] = 1

        # 3. Try moving in 4 directions
        for d, (dxv, dyv) in directions.items():
            nx, ny = x + dxv, y + dyv
            if 1 <= nx <= n and 1 <= ny <= n:
                # Check if we can see a light in this direction
                if can_see_light(lights, x, y, dxv, dyv):
                    # Move
                    path_and_return += d
                    lights[x][y] = 0  # Turn off when leaving
                    result = backtrack(lights, nx, ny, path_and_return[1:-1])
                    if result:
                        lit = lights[nx][ny]
                        lights[nx][ny] = 0
                        path_and_return += result
                        return path_and_return[1:-1]
                    path_and_return += "2"
                    lights[nx][ny] = lit
                    path_and_return = path_and_return[:-1].rstrip()
                    path_and_return += "U"

        return None

    return backtrack(deepcopy(grid), x0, y0, "")

