        edges.append((x - 1, y - 1, w, i + 1))
        adj_list[x].add((y, i + 1))
        adj_list[y].add((x, i + 1))

    def is_reachable(excluded_edge_ids):
        """Check if t is reachable from s when edges are excluded"""
        # Base cases
        if s == t:
            return True

        if s >= n or t >= n:
            return False

        visited = [False] * n
        visited[s] = True
        queue = deque([s])

        while queue:
            u = queue.popleft()

            if u == t:
                return True

            for v, edge_id in adj_list[u + 1]:
                if edge_id in excluded_edge_ids:
                    continue
                if edge_id == -1:  # self-loop or reset marker
                    continue
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)

        return visited[t]

    # Check if already disconnected
    if not is_reachable(set()):
        return "0\n0\n"

    # Try single edge removal
    min_cost = float('inf')
    best_edges = None

    for u, v, w, eid in edges:
        if is_reachable({eid}):
            if w < min_cost:
                min_cost = w
                best_edges = {eid}

    # Try two edge removal
