    # Try pairs
    for i in range(len(edges)):
        for j in range(i + 1, len(edges)):
            excluded = {edges[i][3], edges[j][3]}
            if not is_reachable(excluded):
                cost = edges[i][2] + edges[j][2]
                if cost < min_cost:
                    min_cost = cost
                    best_edges = excluded

    if best_edges is not None:
        edge_list = sorted(best_edges)
        result = [str(min_cost), f"{len(edge_list)}"]
