import collections

def solution(input_str):
    lines = input_str.strip().split('\n')

    n, k = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    # Build prerequisite graph
    adj = collections.defaultdict(list)
    in_degree = collections.defaultdict(int)

    for i in range(n):
        prereq = p[i]
        topic = i + 1
        if prereq != 0:
            adj[prereq].append(topic)
            in_degree[topic] += 1

    # Read all special pairs from remaining lines
    special_adj = collections.defaultdict(list)
    for i in range(k):
        x, y = map(int, lines[2 + i].split())
        special_adj[x].append(y)

    # Build the graph with special pairs as additional edges
    # This models constraints: x MUST be immediately before y
    full_adj = collections.defaultdict(list)
    for u in adj:
        for v in adj[u]:
            full_adj[u].append(v)

    for x in special_adj:
        for y in special_adj[x]:
            full_adj[x].append(y)

    # Recalculate in-degrees in full graph
    full_in_degree = collections.defaultdict(int)
    for u in full_adj:
        for v in full_adj[u]:
            full_in_degree[v] += 1

    # Topological sort with cycle detection
    queue = collections.deque()
    for i in range(1, n + 1):
        if full_in_degree[i] == 0:
            queue.append(i)

    result = []

    while queue:
        node = queue.popleft()
        result.append(node)
        full_in_degree[node] = -1  # Mark as processed

        for neighbor in full_adj[node]:
            full_in_degree[neighbor] -= 1
            if full_in_degree[neighbor] == 0:
                queue.append(neighbor)
    else:
        # Check for cycles - if we have n nodes in result but visited < n
        if len(result) < n:
            full_in_degree[node] = -1  # fix any partial marks
            return '0'

    # If not all nodes processed, cycle exists
    if len(result) < n:
        return '0'

    return ' '.join(map(str, result))

