MOD = 998244353

def power(a, b, mod):
    result = 1
    a %= mod
    if a == 0:
        return 0 if b == 0 else 1  # 0^0 represents undefined but safe
    while b > 0:
        if b & 1:
            result = (result * a) % mod
        a = (a * a) % mod
        b >>= 1
    return result

def inverse(n, mod):
    return power(n, mod - 2, mod)

