    # Checkpoints - initially only mirror 1
    checkpoints = [1]

    def add_checkpoint(u):
        if u not in checkpoints:
            checkpoints.append(u)
            checkpoints.sort()

    def remove_checkpoint(u):
        if u in checkpoints:
            checkpoints.remove(u)

    def compute_expected(p_probs):
        """Compute E[1] given the current checkpoints"""
        # E[n+1] = 0 (success state)
        E = [0] * (n + 2)

        p_mod = [x % MOD for x in p_probs]
        inv_100 = inverse(100, MOD)

        for i in range(n, 0, -1):
            # Find largest checkpoint <= i
            idx = bisect.bisect_right(checkpoints, i) - 1
            if idx < 0:
                next_checkpoint = 1
            else:
                next_checkpoint = checkpoints[idx]

            prob = p[i-1]  # 0-indexed p array

            if next_checkpoint == i:
                # Mirror i is a checkpoint
                # E[i] = 1 + (p/100)*E[i+1] + ((100-p)/100)*E[i]
                # Rearranging: E[i] * (p/100) = 1 + (p/100)*E[i+1]
                inv_p = inverse(prob, MOD)
                E[i] = (100 * inv_p + E[i+1]) % MOD
            else:
                # Mirror i is NOT a checkpoint
                term1 = inv_100 * E[i+1] % MOD
                term2 = inv_100 * (100 - prob) % MOD * E[next_checkpoint] % MOD
                E[i] = (1 + prob * term1 + (100 - prob) * term2) % MOD

        return E[1]

    output = []
    for query_str in lines[2 + q:]:
        u = int(query_str.rstrip())
        if u in checkpoints:
            remove_checkpoint(u)
        else:
            add_checkpoint(u)

