    lines = input_string.strip().split('\n')
    if not lines:
        return "NO"

    n, m = map(int, lines[0].split())

    # Build graph for 2-SAT
    # node 2*(i-1): ¬xi, node 2*(i-1)+1: xi
    graph = [[] for _ in range(2 * m)]

    def get_id(lit):
        """Get node index for literal: positive lit -> odd, negative lit -> even"""
        if lit > 0:
            return 2 * (lit - 1) + 1  # xi -> 2*i+1
        return 2 * (abs(lit) - 1)     # ¬xi -> 2*i-1 (wait, 2*(abs(lit)-1))

    def not_node(u):
        """Node for negation of literal at node u"""
        return u ^ 1

    # Parse all clauses
    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        clause = parts[1:]
        clauses.append(clause)

    # Build implication graph
    for clause in clauses:
        if len(clause) == 2:
            a, b = clause
            u = get_id(a)
            v = get_id(b)
            # (a OR b) implies: ¬a → b, ¬b → a
            graph[not_node(u)].append(v)
            graph[not_node(v)].append(u)

    # Compute SCCs using Kosaraju's algorithm
    visited = [False] * (2 * m)
    order = []

    def dfs(u):
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                dfs(v)
        order.append(u)

    for i in range(2 * m):
        if not visited[i]:
            dfs(i)

    # Build reverse graph and find SCCs
    rev_graph = [[] for _ in range(2 * m)]
    for u in range(2 * m):
        for v in graph[u]:
            rev_graph[v].append(u)

    scc_id = [-1] * (2 * m)
    component_count = 0

    def dfs2(u):
        stack = [u]
        scc_id[u] = component_count
        while stack:
            curr = stack.pop()
            for v in rev_graph[curr]:
                if scc_id[v] == -1:
                    scc_id[v] = component_count
                    stack.append(v)
        component_count += 1

    for i in range(2 * m - 1, -1, -1):
        node = order[i]
        if scc_id[node] == -1:
            dfs2(node)

    # Check for contradiction: xi and ¬xi in same SCC
    for i in range(1, m + 1):
        if scc_id[get_id(i)] == scc_id[get_id(-i)]:
            return "NO"

    return "YES"

def is_gp(arr):
    n = len(arr)
    if n <= 2:
        return True

    # Check if all zeros
    if all(x == 0 for x in arr):
        return True

    # If first element is zero, all subsequent must be zero
    if arr[0] == 0:
        for x in arr[1:]:
            if x != 0:
                return False
        return True

    # Check GP property: arr[i] * arr[0] == arr[1] * arr[i-1]
    for i in range(2, n):
        if arr[i] * arr[0] != arr[1] * arr[i-1]:
            return False

    return True


