                if (edge[1], edge[0]) not in wheel:
                    wheel.add((edge[1], edge[0]))
                    wheel.remove(edge)
                    self.steps.append((edge[0], edge[1]))
                    can_change = True

        return list(self.steps) if not wheel else []


