    is_small = [True] * (sqrt_r + 1)
    is_small[0] = is_small[1] = False
    for i in range(2, int(sqrt_r**0.5) + 1):
        if is_small[i]:
            for j in range(i*i, sqrt_r + 1, i):
                is_small[j] = False
    primes = [i for i, x in enumerate(is_small) if x]

    seg_len = r - l + 1
    is_prime = [True] * seg_len

    for p in primes:
        if p * p > r:
            break
        # ceil(l/p) * p gives first multiple >= l
        start = p if p >= l else ((l + p - 1) // p) * p
        for j in range(start, r + 1, p):
            is_prime[j - l] = False

    # Handle prime p where p>=l
    for p in primes:
        if p >= l and p <= r:
            is_prime[p - l] = True

    # If there are primes we need to add (p <= r but p^2 > r, meaning large primes)
    # These are handled by not marking them (since p >= sqrt(r), p^2 > r)
    # But p itself could be in [l, r]
    for p in primes:
        if l <= p <= r and is_prime_check(p):  # double check
            is_prime[p - l] = True

    def is_prime_check(num):
        if num < 2:
            return False
        for p in primes:
            if p * p > num:
                break
            if p * p > r and p > sqrt_r:
                # Check directly
                return all(num % q != 0 for q in primes if q <= sqrt_r)
            if num % p == 0:
                return False
        if num <= r:
            return True
        return all(num % p != 0 for p in primes if p <= sqrt_r)

    # Recalculate properly
    is_prime_range = [True] * (r - l + 1)
    is_prime_range[0] = False if l == 1 else True  # 1 is not prime

    for p in primes:
        if p * p > r:
            break
        start = ((l + p - 1) // p) * p if p < l else p
        for j in range(start, r + 1, p):
            if j != p:  # Don't mark the prime itself
                is_prime_range[j - l] = False

    # Count and check large primes in [l, r] that weren't divisible by any sqrt_r prime
    result = 0
    for i, val in enumerate(is_prime_range):
        if val:
            prime = l + i
            if prime == 2 or prime % 4 == 1:
