    matching = [-1] * n

    def is_stable():
        # Every city must have exactly one partner
        for i in range(n):
            if matching[i] == -1:
                return False
            # Check mutual: i's partner's partner should be i
            if matching[matching[i]] != i:
                return False

        # Check for blocking pairs
        for i in range(n):
            current_partner_i = matching[i]
            for j in range(n):
                if i == j:
                    continue
                # Different from i, they must have different partners to form a blocking pair
                if matching[j] == current_partner_i:
                    continue
                current_partner_j = matching[j]

                # Blocking pair: both prefer each other over their current partners
                if costs[i][j] < costs[i][current_partner_i] and costs[j][i] < costs[j][current_partner_j]:
                    return False

        return True

    def backtrack():
        # Check if all cities are paired
        all_paired = True
        for i in range(n):
            if matching[i] == -1:
                all_paired = False
                break

        if all_paired:
            return is_stable()

        # Find an unpaired city to try pairing
        for i in range(n):
            if matching[i] == -1:
                # Try pairing i with each j > i
                for j in range(i + 1, n):
                    if matching[j] == -1:
                        # Create mutual pairing
                        matching[i] = j
                        matching[j] = i

                        result = backtrack()
                        if result is True:  # Found stable matching
                            return True

                        # Backtrack
