            total = comb_val * A[p] + total
            if total >= k:
                return True
        return total >= k

    # Binary search over the number of iterations
    left, right = 0, k + 1
    while left < right:
        mid = (left + right) // 2
        total = 0
        for p in range(n):
            r = n - 1 - p
            if r == 0:
                comb_val = 1
            else:
                comb_val = comb(mid + r, r)
            total = comb_val * A[p] + total
            if total >= k:
                break
        if total >= k:
            right = mid
        else:
            left = mid + 1

