    for i in range(m):
        a, b = map(int, lines[1 + i].split())
        edges.append((a, b))

    def are_crossing(i, j):
        a1, b1 = edges[i]
        a2, b2 = edges[j]
        if a1 > b1:
            a1, b1 = b1, a1
        if a2 > b2:
            a2, b2 = b2, a2

        # For edges (a1,b1) and (a2,b2) where a1 < b1 and a2 < b2
        # They cross if a1 < a2 < b1 < b2 or a2 < a1 < b2 < b1
        if a1 < a2:
            return a2 < b1 and b1 < b2
        if a2 < a1:
            return a1 < b2 and b2 < b1
        return False

    # Check if all edges can be inside
    if not any(are_crossing(i, j) for i in range(m) for j in range(i+1, m)):
        return 'i' * m

    # Check if all edges can be outside
    if not any(are_crossing(i, j) for i in range(m) for j in range(i+1, m)):
        return 'o' * m

    # Backtracking to find valid assignment
    def backtrack(idx, assignment):
        if idx == m:
            return True

        for color in ['i', 'o']:
            valid = True
            for prev in range(idx):
                if are_crossing(idx, prev) and assignment[prev] == color:
                    valid = False
                    break
            if valid:
                assignment.append(color)
                if backtrack(idx + 1, assignment):
                    return True
                assignment.pop()

        return False

    assignment = []
    if backtrack(0, assignment):
        return ''.join(assignment)

    return 'Impossible'

