    # cum[0] = 0, cum[1] = d[0], cum[2] = d[0]+d[1], etc.
    cum = [0] * (n + 1)
    for i in range(n):
        cum[i + 1] = cum[i] + d[i]

    total_perimeter = cum[n]

    def dist_0(a, b):
        """Compute distance between trees at 0-indexed positions a and b,
           going forward (clockwise) via the arc that doesn't contain children"""
        if a <= b:
            return cum[b] - cum[a]
        else:
            return total_perimeter - (cum[a] - cum[b])

    results = []

    for i in range(m):
        a, b = map(int, lines[3 + i].split())

        # Forbidden ranges in 1-indexed:
        # If a <= b: forbidden = [a, b]
        # If a > b: forbidden = [b, n] U [1, a]

        valid_trees = []
        if a <= b:
            # Valid: [1, a-1] and [b+1, n] in 1-indexed
            if a > 1:
                for t in range(1, a):
                    valid_trees.append(t)
            if b < n:
                for t in range(b + 1, n + 1):
                    valid_trees.append(t)
        else:
            # Valid: [a+1, b-1] in 1-indexed
            if a + 1 <= b - 1:
                for t in range(a + 1, b):
                    valid_trees.append(t)

