    pos = {p[i]: i for i in range(n)}
    assignment = [-1] * n
    processed = set()

    # Build graph: numbers that must be in same set are connected
    graph = [[] for _ in range(n)]
    for i in range(n):
        x = p[i]
        # If x is in A, (a-x) must also be in A (same connectivity)
        if a - x in pos:
            j = pos[a - x]
            if i != j:
                graph[i].append(j)
                graph[j].append(i)
        # If x is in B, (b-x) must also be in B (same connectivity)
        if b - x in pos:
            j = pos[b - x]
            if i != j:
                graph[i].append(j)
                graph[j].append(i)

    def get_component(start):
        """BFS to find all nodes in component"""
        component = []
        queue = [start]
        comp_set = {start}
        while queue:
            u = queue.pop(0)
            component.append(u)
            for v in graph[u]:
                if v not in comp_set:
                    comp_set.add(v)
                    queue.append(v)
        return component

    def can_assign_to_a(comp):
        """Check if component can all go to set A"""
        for u in comp:
            x = p[u]
            if a - x in pos:
                v = pos[a - x]
                if v not in comp:
                    return False
                if assignment[v] != -1 and assignment[v] == 1:
                    return False  # v is already in B but constraint requires A
        return True

    def can_assign_to_b(comp):
        """Check if component can all go to set B"""
        for u in comp:
            x = p[u]
            if b - x in pos:
                v = pos[b - x]
                if v not in comp:
                    return False
                if assignment[v] != -1 and assignment[v] == 0:
                    return False  # v is already in A but constraint requires B
        return True

    for i in range(n):
        if i in processed:
            continue

        component = get_component(i)
        processed.update(component)

        # Try assigning all to set A first
        if can_assign_to_a(component):
            for u in component:
