        if d == 0:
            continue

        # Try each element as starting point
        for start_idx in range(n):
            x = a[start_idx]
            generated = {(x + k * d) % m for k in range(n)}
            if generated == set(a):
                return f"{x} {d}\n"

    return "-1\n"

