            if f['ai'] == 0:
                break

        # Actually a jump for ai cells means we check ai + 1 cells
        # But we need to handle the path properly

        # Simpler approach: simulate each step of the path
        knocked_idx = set()

        # Path includes all cells visited during jump
        temp_pos = f['pos']
        for step in range(f['ai']):
            temp_pos = (temp_pos + 1) % m
            if temp_pos in cell_to_frog:
                knocked_idx.add(cell_to_frog[temp_pos])

        # Include the destination
        if new_pos in cell_to_frog:
            if new_pos != f['pos']:
                knocked_idx.add(cell_to_frog[new_pos])

        # Actually re-think: jump means moving frog's current position forward
        # The path includes: current_pos, current_pos+1, ..., current_pos + ai (wrapping)
        # But we start at current_pos, and each step we check if there's a frog

        knocked_set = set()
        current = f['pos']
        for _ in range(f['ai']):
            current = (current + 1) % m
            if current in cell_to_frog:
                idx = cell_to_frog[current]
                if idx != frog_idx:
                    knocked_set.add(idx)

        # Also check the final landing position
        if new_pos in cell_to_frog:
            if new_pos != f['pos']:
                idx = cell_to_frog[new_pos]
                if idx != frog_idx:
                    knocked_set.add(idx)

        # Update frogs knocked out
        for idx in knocked_set:
            frogs[idx]['active'] = False
            del cell_to_frog[frogs[idx]['pos']]

        f['ai'] -= len(knocked_set)

        return f['ai'] > 0

    # Try to simulate
    changed = True
    while changed:
        changed = False
        for i in all_frog_keys:
            if frogs[i]['active'] and frogs[i]['ai'] > 0:
                moved = move_frog(i, m)
                if moved:
                    changed = True

        # Rebuild cell_to_frog after all updates
        cell_to_frog = {}
        for k in frogs.keys():
            if frogs[k]['active']:
                cell_to_frog[frogs[k]['pos']] = k

    # Debug: print state
    active_frogs = [k for k in frogs.keys() if frogs[k]['active']]
    result_ids = [frogs[k]['id'] for k in active_frogs]
    result_ids.sort()

    return f"{len(result_ids)}\n{' '.join(map(str, result_ids))} "

from functools import lru_cache

MOD = 10**9 + 7

def solution(x_str):
    s = x_str.strip()

    # Handle small inputs directly
    if len(s) <= 16:
        n = int(s)
        total = 0
        for i in range(1, n + 1):
            val = int(''.join(sorted(str(i))))
            total = (total + val) % MOD
        return str(total)

    # For large inputs, use digit DP approach
    N = len(s)

    @lru_cache(None)
    def dp(pos, tight, leading_zeros):
        if pos == N:
            return (1, 0)  # (count, sum)

        limit = int(s[pos]) if tight else 9

        count = 0
        s_sum = 0

        for d in range(limit + 1):
            new_tight = tight and (d == limit)
            new_leading = leading_zeros and (d == 0)

            if pos == 0 and d == 0:
                continue

            cnt, ss = dp(pos + 1, new_tight, new_leading)

            if cnt > 0:
                # d contributes to sorted position - simplified
                contrib = d * cnt
                count = (count + cnt) % MOD
                s_sum = (s_sum + ss + contrib) % MOD

        return (count % MOD, s_sum % MOD)

    cnt, total = dp(0, True, True)
    return str(total)
